<!-- ---------- chatbot widget ---------- -->
<button class="cb-launcher" id="cbLauncher" aria-label="افتح شات الدعم">
  <span class="cb-dot"></span>
  <svg class="cb-chat-ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 11.5a8.4 8.4 0 01-.9 3.8 8.5 8.5 0 01-7.6 4.7 8.4 8.4 0 01-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 01-.9-3.8 8.5 8.5 0 014.7-7.6 8.4 8.4 0 013.8-.9h.5a8.48 8.48 0 018 8v.5z"/></svg>
  <svg class="cb-close-ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M18 6L6 18M6 6l12 12"/></svg>
</button>

<div class="cb-panel" id="cbPanel">
  <div class="cb-head">
    <div class="avatar">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 2l8 4v6c0 5-3.5 8.5-8 10-4.5-1.5-8-5-8-10V6l8-4z"/></svg>
    </div>
    <div class="cb-head-info">
      <b>مساعد صنعة</b>
      <span>متاح دلوقتي</span>
    </div>
  </div>
  <div class="cb-body" id="cbBody"></div>
  <div class="cb-input-row">
    <input type="text" id="cbInput" placeholder="اكتب رسالتك هنا...">
    <button id="cbSend" aria-label="إرسال">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 12l16-8-6 16-3-7-7-1z"/></svg>
    </button>
  </div>
</div>


<script>
(function(){
  const launcher = document.getElementById('cbLauncher');
  const panel = document.getElementById('cbPanel');
  const body = document.getElementById('cbBody');
  const input = document.getElementById('cbInput');
  const sendBtn = document.getElementById('cbSend');
  let opened = false;
  let greeted = false;

  function addMessage(text, who){
    const div = document.createElement('div');
    div.className = 'cb-msg ' + who;
    div.textContent = text;
    body.appendChild(div);
    body.scrollTop = body.scrollHeight;
    return div;
  }

  function addQuickReplies(options){
    const wrap = document.createElement('div');
    wrap.className = 'cb-quick';
    options.forEach(opt => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.textContent = opt;
      btn.addEventListener('click', () => handleUserMessage(opt));
      wrap.appendChild(btn);
    });
    body.appendChild(wrap);
    body.scrollTop = body.scrollHeight;
  }

  function showTyping(){
    const t = document.createElement('div');
    t.className = 'cb-typing';
    t.id = 'cbTypingNow';
    t.innerHTML = '<span></span><span></span><span></span>';
    body.appendChild(t);
    body.scrollTop = body.scrollHeight;
  }
  function hideTyping(){
    const t = document.getElementById('cbTypingNow');
    if(t) t.remove();
  }

  function botReplyFor(msg){
    const m = msg.trim();
    if(/سعر|تكلفة|فلوس|كام/.test(m)) return 'الأسعار بتختلف حسب نوع الشغل والمنطقة، بس تقدر تشوف تفاصيل الاشتراكات والعمولة في قسم "الاشتراكات" في الصفحة، أو تطلب صنايعي وهياخد لك عرض سعر مجاني.';
    if(/صنايعي|طلب|احجز/.test(m)) return 'تمام! تقدر تطلب صنايعي دلوقتي من زرار "اطلب صنايعي" في أول الصفحة، هيوصلك صنايعي موثّق وقريب منك في دقايق.';
    if(/تسجيل|انضم|اشتغل معاكم/.test(m)) return 'لو عايز تنضم كصنايعي، روح لقسم "سجّل كصنايعي" وهتلاقي شروط الانضمام وخطوات التسجيل كاملة.';
    if(/ضمان|امان|امن/.test(m)) return 'كل صنايعي عندنا بيعدي فحص جنائي وموثّق، وكل شغلانة فيها ضمان 14 يوم.';
    if(/شكرا|تمام|ok|اوك/i.test(m)) return 'العفو! تحت أمرك في أي وقت 🙏';
    return 'استلمت رسالتك، وحد من فريق الدعم هيتواصل معاك في أقرب وقت. تقدر كمان تختار من الأسئلة الشائعة تحت.';
  }

  function handleUserMessage(text){
    if(!text || !text.trim()) return;
    addMessage(text, 'user');
    input.value = '';
    showTyping();
    setTimeout(() => {
      hideTyping();
      addMessage(botReplyFor(text), 'bot');
    }, 700 + Math.random()*500);
  }

  function greet(){
    if(greeted) return;
    greeted = true;
    addMessage('أهلاً بيك في صنعة 👋 أنا هنا أساعدك تلاقي صنايعي موثّق أو تجاوب على أي سؤال.', 'bot');
    addQuickReplies(['عايز أطلب صنايعي', 'استفسار عن الأسعار', 'عايز أسجل كصنايعي']);
  }

  function togglePanel(){
    opened = !opened;
    launcher.classList.toggle('open', opened);
    panel.classList.toggle('open', opened);
    if(opened){
      greet();
      setTimeout(() => input.focus(), 260);
    }
  }

  launcher.addEventListener('click', togglePanel);
  sendBtn.addEventListener('click', () => handleUserMessage(input.value));
  input.addEventListener('keydown', (e) => { if(e.key === 'Enter') handleUserMessage(input.value); });
})();
</script>

<script>
  // registration tabs
  function switchTab(which){
    const clientBtn = document.getElementById('tabClientBtn');
    const proBtn = document.getElementById('tabProBtn');
    const clientBody = document.getElementById('tabClient');
    const proBody = document.getElementById('tabPro');
    if(which === 'pro'){
      proBtn.classList.add('active'); clientBtn.classList.remove('active');
      proBody.classList.add('active'); clientBody.classList.remove('active');
    } else {
      clientBtn.classList.add('active'); proBtn.classList.remove('active');
      clientBody.classList.add('active'); proBody.classList.remove('active');
    }
    const target = document.getElementById('join');
    if(target) target.scrollIntoView({behavior:'smooth', block:'start'});
  }

  // mobile menu
  const burger = document.getElementById('burger');
  const navLinks = document.getElementById('navLinks');
  burger.addEventListener('click', () => navLinks.classList.toggle('open'));
  navLinks.querySelectorAll('a').forEach(a => a.addEventListener('click', () => navLinks.classList.remove('open')));

  // scroll reveal
  const io = new IntersectionObserver((entries) => {
    entries.forEach(e => { if(e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); } });
  }, {threshold:.15});
  document.querySelectorAll('.reveal').forEach(el => io.observe(el));

  // counters
  const counters = document.querySelectorAll('.counter');
  const cio = new IntersectionObserver((entries) => {
    entries.forEach(e => {
      if(e.isIntersecting){
        const el = e.target;
        const target = +el.dataset.target;
        let cur = 0;
        const step = Math.max(1, Math.round(target/40));
        const t = setInterval(() => {
          cur += step;
          if(cur >= target){ cur = target; clearInterval(t); }
          el.textContent = cur;
        }, 30);
        cio.unobserve(el);
      }
    });
  }, {threshold:.4});
  counters.forEach(c => cio.observe(c));
</script>
</body>
</html>
